from pathlib import Path
import os,subprocess,time,json,sys,shlex
p=Path('/tmp/interval-refactor/rk-proposal')
commands=[('padding-release', 'cargo run --release --locked --manifest-path /tmp/interval-refactor/rk-proposal/padding-mode-project/Cargo.toml --target-dir /tmp/interval-refactor/rk-padding-target', {}, '/mnt/development/csgrs'), ('rk-debug', 'cargo test --locked -p hyperdynamics --all-features --test rk_proposal', {}, '/mnt/development/csgrs'), ('rk-minimal', 'cargo test --locked -p hyperdynamics --no-default-features --features rk-proposal --test rk_proposal', {}, '/mnt/development/csgrs'), ('rk-msrv', 'cargo +1.95.0 test --locked -p hyperdynamics --all-features --test rk_proposal', {}, '/mnt/development/csgrs'), ('rk-release', 'cargo test --locked --release -p hyperdynamics --all-features --test rk_proposal --test field_construction_trace', {}, '/mnt/development/csgrs'), ('rk-asan', 'cargo +nightly test --locked --target x86_64-unknown-linux-gnu -p hyperdynamics --all-features --test rk_proposal', {'RUSTFLAGS': '-Zsanitizer=address', 'CARGO_TARGET_DIR': '/tmp/interval-refactor/dyadic-evolution-asan'}, '/mnt/development/csgrs'), ('native-modes', 'cargo test --locked --release -p hyperinterval --all-features --test float --test dyadic_float_ingress', {}, '/mnt/development/csgrs'), ('accepted-core', 'cargo test --locked -p hyperdynamics --all-features --all-targets', {}, '/mnt/development/csgrs-field-core'), ('clippy', 'cargo clippy --locked -p hyperdynamics -p hyperinterval --all-features --all-targets -- -D warnings', {}, '/mnt/development/csgrs'), ('docs', 'cargo doc --locked -p hyperdynamics --all-features --no-deps', {'RUSTDOCFLAGS': '-D warnings'}, '/mnt/development/csgrs'), ('wasm', 'cargo check --locked -p hyperdynamics --all-features --target wasm32-unknown-unknown --lib', {}, '/mnt/development/csgrs'), ('example', 'cargo run --locked -p hyperdynamics --features rk-proposal --example rk_proposal', {}, '/mnt/development/csgrs'), ('cost-build', 'cargo build --release --locked --manifest-path /tmp/interval-refactor/rk-proposal/rk-cost-project/Cargo.toml --target-dir /tmp/interval-refactor/rk-cost-target', {}, '/mnt/development/csgrs'), ('fmt', 'cargo fmt --all -- --check', {}, '/mnt/development/csgrs')]

rows=[]
for name,cmd,env,cwd in commands:
 start=time.monotonic();log='padding-final-'+name+'.log'
 with (p/log).open('w') as f:r=subprocess.run(shlex.split(cmd),env=os.environ|env,cwd=cwd,stdout=f,stderr=subprocess.STDOUT,timeout=900)
 rows.append(dict(name=name,command=cmd,cwd=cwd,env=env,returncode=r.returncode,seconds=time.monotonic()-start,log=log))
 (p/'padding-final-checks.json').write_text(json.dumps(rows,indent=2)+'\n');print(name,r.returncode,flush=True)
 if r.returncode:sys.exit(r.returncode)
